/** Complete printable comparison of two retained collection source editions. */
const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const text=value=>escapeHtml(value).replace(/\r\n?|\n/g,'<br>');
const array=value=>Array.isArray(value)?value:[];
const present=value=>typeof value==='string'?value:JSON.stringify(value,null,2)??'Not recorded';
const humanTime=value=>value&&Number.isFinite(Date.parse(value))?new Intl.DateTimeFormat('en-US',{year:'numeric',month:'short',day:'numeric',hour:'numeric',minute:'2-digit',hour12:true,timeZone:'UTC'}).format(new Date(value))+' UTC':value||'Not recorded';
function safeUrl(value){
 if(typeof value!=='string'||/[\u0000-\u0020\u007f\\<>"']/.test(value))return null;
 const match=value.match(/^https?:\/\/([^/?#]+)(?:[/?#]|$)/i);if(!match||match[1].includes('@'))return null;
 return value;
}
const link=(url,label)=>safeUrl(url)?'<a href="'+escapeHtml(url)+'" rel="noopener noreferrer">'+text(label||url)+'</a>':text(label||url||'Not recorded');
const code=value=>'<code>'+escapeHtml(value??'Not recorded')+'</code>';
const sourceSpan=entry=>entry?.sourceLocator&&Number.isSafeInteger(entry.sourceLocator.start)&&Number.isSafeInteger(entry.sourceLocator.end)?'UTF-8 byte range '+entry.sourceLocator.start+'–'+entry.sourceLocator.end+' (end exclusive)':typeof entry?.sourceLocator?.jsonPointer==='string'?'Original JSON location '+entry.sourceLocator.jsonPointer:'Source location not recorded';
const institution=edition=>typeof edition?.institution==='string'?edition.institution:edition?.institution?.title||'Institution not recorded';
function entryCard(entry,prefix=''){
 if(!entry)return '<p class="muted">No selected target.</p>';
 return '<div class="entry-card"><p class="record">'+escapeHtml(prefix)+(prefix?' · ':'')+'Occurrence '+escapeHtml(entry.ordinal)+'</p><p class="original-title">'+text(entry.title)+'</p><p>'+link(entry.url,'Open institution record')+'</p><p class="meta">'+escapeHtml(sourceSpan(entry))+'</p><p class="meta">'+code(entry.id)+'</p></div>';
}
function changesTable(changes){
 if(!array(changes).length)return '<p class="muted">No field differences are recorded in this comparison.</p>';
 return '<table class="changes"><thead><tr><th>Field</th><th>Earlier value</th><th>Later value</th></tr></thead><tbody>'+changes.map(change=>'<tr><th scope="row">'+text(change.field)+'</th><td><pre>'+escapeHtml(present(change.before))+'</pre></td><td><pre>'+escapeHtml(present(change.after))+'</pre></td></tr>').join('')+'</tbody></table>';
}
function editionCard(edition,label){
 const s=edition.source||{};
 return '<section class="edition"><h2>'+escapeHtml(label)+'</h2><p class="institution">'+text(institution(edition))+'</p><dl><dt>Retained file</dt><dd>'+text(s.filename||'Not recorded')+'</dd><dt>Format</dt><dd>'+text(s.format||'Not recorded')+'</dd><dt>Observed</dt><dd>'+text(humanTime(s.observedAt))+'</dd><dt>Source size</dt><dd>'+text(Number.isSafeInteger(s.bytes)?s.bytes.toLocaleString('en-US')+' bytes':'Not recorded')+'</dd><dt>Published source</dt><dd>'+link(s.url)+'</dd></dl><p class="meta">SHA-256 '+code(s.sha256)+'</p><p class="meta">Retained edition '+code(edition.id)+'</p></section>';
}
function carryList(decision){
 const entries=[['Review text',decision.carryReview],['Rights statement',decision.carryRights],['Story position',decision.carryStory],['Relationships',decision.carryRelationships]];
 return '<dl class="carry">'+entries.map(([name,value])=>'<dt>'+name+'</dt><dd>'+(value===true?'Carry if this correspondence is applied':'Keep only in the earlier review')+'</dd>').join('')+'</dl>';
}
function priorReview(review){
 if(!review)return '<p class="muted">No attributed review is recorded for this earlier occurrence.</p>';
 const rights=review.rights||{};
 return '<div class="prior"><h4>Earlier editorial review</h4><dl><dt>Review status</dt><dd>'+text(review.status||'unreviewed')+'</dd><dt>Proposed title</dt><dd>'+text(review.suggestedTitle||'None recorded')+'</dd><dt>Summary</dt><dd>'+text(review.summary||'None recorded')+'</dd><dt>Review note</dt><dd>'+text(review.note||'None recorded')+'</dd><dt>Rights status</dt><dd>'+text(rights.status||'unknown')+'</dd><dt>Rights basis</dt><dd>'+text(rights.basis||'None recorded')+'</dd><dt>Rights citation</dt><dd>'+link(rights.citation)+'</dd></dl></div>';
}
const CSS=':root{color-scheme:light;font:14px/1.55 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#252525;background:#efefef}*{box-sizing:border-box}body{margin:0}main{max-width:1220px;margin:28px auto;padding:30px;background:#fff;border:1px solid #c7c7c7}h1{font-size:28px;line-height:1.2;margin:0 0 12px}h2{font-size:19px;line-height:1.3;margin:0 0 14px}h3{font-size:16px;line-height:1.4;margin:0}h4{font-size:14px;margin:0 0 8px}p{margin:7px 0}.eyebrow{text-transform:uppercase;letter-spacing:.13em;font-size:11px;font-weight:700;color:#626262}.lede{max-width:85ch;font-size:15px}.meta,.muted{font-size:12px;color:#585858}.meta{overflow-wrap:anywhere}.summary{display:flex;flex-wrap:wrap;border:1px solid #bcbcbc;margin:22px 0}.metric{flex:1 1 145px;padding:12px 16px;border-right:1px solid #ddd}.metric strong{display:block;font-size:23px;font-weight:650}.metric span{font-size:12px;color:#555}.notice{border-left:4px solid #343434;padding:12px 16px;background:#f1f1f1;margin:18px 0}.editions{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin:24px 0}.edition{border:1px solid #c5c5c5;padding:17px;min-width:0}.institution{font-weight:600}dl{display:grid;grid-template-columns:minmax(100px,.6fr) minmax(0,1.8fr);gap:5px 14px;margin:12px 0}dt{font-weight:600}dd{margin:0;overflow-wrap:anywhere}section.major{margin-top:30px;border-top:2px solid #444;padding-top:19px}table{width:100%;border-collapse:collapse;margin:12px 0;font-size:12px;table-layout:fixed}th,td{padding:9px 10px;text-align:left;vertical-align:top;border:1px solid #ccc;overflow-wrap:anywhere}th{background:#eeeeee;font-weight:650}.changes th:first-child{width:18%}pre{white-space:pre-wrap;overflow-wrap:anywhere;word-break:break-word;font:12px/1.5 ui-monospace,SFMono-Regular,Consolas,monospace;margin:0}code{font:11px/1.5 ui-monospace,SFMono-Regular,Consolas,monospace;overflow-wrap:anywhere;word-break:break-word}a{color:inherit;text-underline-offset:2px}.row{border:1px solid #bcbcbc;margin:18px 0;padding:18px;break-inside:avoid}.row-header{display:flex;justify-content:space-between;align-items:start;gap:12px;border-bottom:1px solid #ddd;padding-bottom:12px;margin-bottom:14px}.status{font-size:11px;text-transform:uppercase;letter-spacing:.06em;border:1px solid #888;padding:4px 7px;white-space:nowrap}.pair{display:grid;grid-template-columns:1fr 1fr;gap:20px}.entry-card{min-width:0}.record{font-size:12px;font-weight:650;color:#555}.original-title{font-weight:650;font-size:15px;overflow-wrap:anywhere}.candidate-list{padding-left:22px}.candidate-list li{padding:8px 0;border-bottom:1px solid #ddd;break-inside:avoid}.candidate-list p{font-size:12px}.decision{margin:16px 0;padding:13px;background:#f3f3f3}.carry{font-size:12px}.prior{margin-top:15px;border-top:1px solid #ddd;padding-top:13px;font-size:12px}.added-list{padding-left:23px}.added-list li{padding:11px 0;border-bottom:1px solid #ccc;break-inside:avoid}.omitted{font-size:12px;overflow-wrap:anywhere;padding-left:22px}footer{font-size:12px;color:#555;margin-top:32px;border-top:1px solid #bbb;padding-top:15px}@media(max-width:720px){main{margin:0;padding:18px;border:0}.editions,.pair{display:block}.edition,.entry-card{margin-bottom:16px}.row{padding:12px}.row-header{display:block}.status{display:inline-block;margin-top:8px}dl{grid-template-columns:1fr}dd{margin-bottom:6px}.changes th,.changes td{padding:6px}.metric{flex-basis:45%;border-bottom:1px solid #ddd}}@media print{@page{size:A4;margin:13mm}body{background:#fff}main{border:0;margin:0;padding:0;max-width:none;font-size:10pt}h1{font-size:21pt}h2{font-size:15pt}h3{font-size:12pt}.row{break-inside:auto}.pair,.row-header,.edition,.entry-card,.decision,.prior{break-inside:avoid}.changes tr{break-inside:avoid}thead{display:table-header-group}a{text-decoration:none}.metric strong{font-size:17pt}.meta,code,pre,table,.carry,.prior{font-size:8pt}.major{break-before:auto}.editions{gap:12px}}';
export function renderCollectionEditionComparison(report){
 if(!report||report.schema!=='stellar-forge.collection-edition-comparison.v1'||!report.workspace||!report.from||!report.to||!Array.isArray(report.rows)||!Array.isArray(report.added))throw new Error('Open a complete collection source-edition comparison.');
 const oldIds=new Set(),mappedIds=new Map();
 for(const row of report.rows){if(!row.from?.id||oldIds.has(row.from.id)||!Array.isArray(row.candidates)||!['unresolved','map','omit'].includes(row.decision?.action))throw new Error('The comparison contains an invalid or repeated earlier occurrence.');oldIds.add(row.from.id);if(row.decision.action==='map'&&row.decision.toId)mappedIds.set(row.decision.toId,(mappedIds.get(row.decision.toId)||0)+1);}
 const mapped=report.rows.filter(row=>row.decision.action==='map').length,omitted=report.rows.filter(row=>row.decision.action==='omit').length,unresolved=report.rows.filter(row=>row.decision.action==='unresolved').length,ambiguous=report.rows.filter(row=>(row.candidateCount??row.candidates.length)>1).length,collisions=[...mappedIds.values()].filter(n=>n>1).length;
 const complete=!report.preparationError&&Boolean(report.effects)&&unresolved===0&&collisions===0&&report.rows.every(row=>row.decision.action!=='map'||row.selected?.id===row.decision.toId);
 const metrics=[['Earlier occurrences',report.rows.length],['Later occurrences',report.counts?.after??'Not recorded'],['Mapped',mapped],['Omitted',omitted],['Unresolved',unresolved],['Candidate ambiguities',ambiguous],['Later additions',report.added.length]];
 const title=report.workspace.name||'Collection source-edition comparison';
 const rows=report.rows.map((row,index)=>{
  const d=row.decision,selected=row.selected,collision=d.toId&&(mappedIds.get(d.toId)||0)>1;
  const label=d.action==='map'?'Mapped':d.action==='omit'?'Omitted from transfer':'Unresolved';
  const candidates=row.candidates.length?'<p class="meta">Showing '+row.candidates.length+' of '+escapeHtml(row.candidateCount??row.candidates.length)+' suggested candidates. The complete later source remains in the editable workspace.</p><ol class="candidate-list">'+row.candidates.map(candidate=>'<li><p><strong>'+text(candidate.title)+'</strong></p><p>Later occurrence '+escapeHtml(candidate.ordinal)+' · suggestion basis: '+text(candidate.match||'Not recorded')+'</p><p>'+link(candidate.url,'Open institution record')+'</p><p class="meta">'+code(candidate.id)+'</p></li>').join('')+'</ol>':'<p class="muted">No correspondence candidates were suggested.</p>';
  return '<article class="row"><div class="row-header"><h3>'+(index+1)+'. Earlier occurrence '+escapeHtml(row.from.ordinal)+'</h3><span class="status">'+label+'</span></div><div class="pair">'+entryCard(row.from,'Earlier source')+entryCard(selected,'Selected later source')+'</div><div class="decision"><h4>Recorded correspondence choice</h4><p>'+text(d.note||'No decision note recorded.')+'</p>'+(collision?'<p><strong>This later occurrence is selected by more than one earlier occurrence. Resolve the collision before applying.</strong></p>':'')+(d.action==='map'?carryList(d):'<p>'+(d.action==='omit'?'This occurrence remains in the earlier source and review. Its editorial content is not carried into the later-source draft by this choice.':'No editorial transfer is resolved for this occurrence.')+'</p>')+'</div><h4>Compared fields</h4>'+changesTable(row.changes)+'<h4>Candidate suggestions</h4>'+candidates+priorReview(row.previousReview)+'</article>';
 }).join('');
 const omittedReviewList=(title,ids)=>'<h3>'+escapeHtml(title)+'</h3>'+(array(ids).length?'<ul class="omitted">'+ids.map(id=>{const row=report.rows.find(r=>r.from.id===id);return '<li>'+(row?'Earlier occurrence '+escapeHtml(row.from.ordinal)+' · '+text(row.from.title)+'<br>':'')+code(id)+'</li>';}).join('')+'</ul>':'<p class="muted">None recorded.</p>');
 const effects=report.effects?'<div class="summary">'+[['Reviews carried',report.effects.reviewsCarried],['Rights statements carried',report.effects.rightsCarried],['Story occurrences carried',report.effects.storyCarried],['Relationships carried',report.effects.relationshipsCarried]].map(([label,value])=>'<div class="metric"><strong>'+escapeHtml(value??0)+'</strong><span>'+label+'</span></div>').join('')+'</div>'+omittedReviewList('Earlier reviews left out of the proposed draft',report.effects.reviewsOmitted)+omittedReviewList('Earlier rights statements reset to unknown',report.effects.rightsReset)+'<h3>Earlier story references left out of the proposed draft</h3>'+(array(report.effects.storyOmitted).length?'<ul class="omitted">'+report.effects.storyOmitted.map(id=>'<li>'+code(id)+'</li>').join('')+'</ul>':'<p class="muted">None recorded.</p>')+'<h3>Earlier relationship references left out of the proposed draft</h3>'+(array(report.effects.relationshipsOmitted).length?'<ul class="omitted">'+report.effects.relationshipsOmitted.map(id=>'<li>'+code(id)+'</li>').join('')+'</ul>':'<p class="muted">None recorded.</p>'):'<p>The comparison does not yet contain a completed transfer projection.</p>';
 const added=report.added.length?'<ol class="added-list">'+report.added.map(entry=>'<li>'+entryCard(entry,'Later source')+'</li>').join('')+'</ol>':'<p>No later additions are recorded by this comparison.</p>';
 return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+escapeHtml(title)+' · Source editions</title><style>'+CSS+'</style></head><body><main><header><p class="eyebrow">Collection Review · Source maintenance</p><h1>'+text(title)+'</h1><p class="lede">Compare retained catalogue editions and review how editorial work would move between their original occurrences.</p><p class="meta">Saved editorial basis '+code(report.basisRevision)+'</p></header><div class="summary">'+metrics.map(([label,value])=>'<div class="metric"><strong>'+escapeHtml(value)+'</strong><span>'+label+'</span></div>').join('')+'</div><div class="notice"><strong>'+(complete?'Correspondence choices and projected effects are complete.':'Correspondence still needs review.')+'</strong>'+(report.preparationError?'<p><strong>Preparation needs attention:</strong> '+text(report.preparationError)+'</p>':'')+'<p>Candidate matches are suggestions. This report describes the recorded choices and projected effects; it does not itself apply a transfer or establish media rights. A completed transfer requires an explicit, one-to-one correspondence and the application’s original save request.</p></div><div class="editions">'+editionCard(report.from,'Earlier retained source')+editionCard(report.to,'Later retained source')+'</div><section class="major"><h2>Institution and source metadata differences</h2>'+changesTable(report.metadataChanges)+'</section><section class="major"><h2>Complete occurrence correspondence</h2><p>Original titles, links and source locations remain separate from the correspondence decisions. Omission from transfer leaves the earlier source and saved review available.</p>'+rows+'</section><section class="major"><h2>Later-source additions</h2>'+added+'</section><section class="major"><h2>Projected editorial effects</h2>'+effects+'</section><footer><p>Only explicitly selected editorial fields move into a later-source draft. A carried rights statement remains its original operator-recorded statement and basis; this comparison does not independently establish that it applies to a changed record. Source history, saved reviews and unfinished earlier working text remain in the complete workspace.</p><p>Workspace '+code(report.workspace.id)+'</p></footer></main></body></html>';
}
